   157→        my $sub = Chalk::IR::Node->new(
   158→            id => $node_id,
   159→            op => 'Sub',
   160→            inputs => [$current_control, $left_node->id, $right_node->id],
   161→            attributes => $attributes
   162→        );
   163→        $graph->add_node($sub);
   164→        return $sub;
   165→    }
