   167→    method build_divide_node($left_node, $right_node) {
   168→        my $left_ref = { op => 'NodeRef', node_id => $left_node->id };
   169→        my $right_ref = { op => 'NodeRef', node_id => $right_node->id };
   170→        my $attributes = {
   171→            left => $left_ref,
   172→            right => $right_ref
   173→        };
