   175→        my $div = Chalk::IR::Node->new(
   176→            id => $node_id,
   177→            op => 'Div',
   178→            inputs => [$current_control, $left_node->id, $right_node->id],
   179→            attributes => $attributes
   180→        );
   181→        $graph->add_node($div);
   182→        return $div;
   183→    }
