   235→    # Create Proj node (projection from MultiNode like Start)
   236→    method build_proj_node($source_node, $index, $label) {
   237→        my $attributes = {
   238→            index => $index,
   239→            label => $label
   240→        };
   241→        my $node_id = $self->next_node_id();
   242→        my $proj = Chalk::IR::Node->new(
   243→            id => $node_id,
   244→            op => 'Proj',
   245→            inputs => [$source_node->id],
   246→            attributes => $attributes
   247→        );
   248→        $graph->add_node($proj);
   249→        return $proj;
   250→    }
