   252→    # Comparison nodes
   253→    method build_greater_node($left_node, $right_node) {
   254→        my $left_ref = { op => 'NodeRef', node_id => $left_node->id };
   255→        my $right_ref = { op => 'NodeRef', node_id => $right_node->id };
   256→        my $attributes = {
   257→            left => $left_ref,
   258→            right => $right_ref
   259→        };
   260→        my $node_id = $self->next_node_id();
   261→        my $cmp = Chalk::IR::Node->new(
   262→            id => $node_id,
   263→            op => 'Greater',
   264→            inputs => [$current_control, $left_node->id, $right_node->id],
   265→            attributes => $attributes
   266→        );
   267→        $graph->add_node($cmp);
   268→        return $cmp;
   269→    }
