   271→    method build_less_node($left_node, $right_node) {
   272→        my $left_ref = { op => 'NodeRef', node_id => $left_node->id };
   273→        my $right_ref = { op => 'NodeRef', node_id => $right_node->id };
   274→        my $attributes = {
   275→            left => $left_ref,
   276→            right => $right_ref
   277→        };
   278→        my $node_id = $self->next_node_id();
   279→        my $cmp = Chalk::IR::Node->new(
   280→            id => $node_id,
   281→            op => 'Less',
   282→            inputs => [$current_control, $left_node->id, $right_node->id],
   283→            attributes => $attributes
   284→        );
   285→        $graph->add_node($cmp);
   286→        return $cmp;
   287→    }
   288→
   289→    method build_equal_node($left_node, $right_node) {
   290→        my $left_ref = { op => 'NodeRef', node_id => $left_node->id };
   291→        my $right_ref = { op => 'NodeRef', node_id => $right_node->id };
   292→        my $attributes = {
   293→            left => $left_ref,
   294→            right => $right_ref
   295→        };
   296→        my $node_id = $self->next_node_id();
   297→        my $cmp = Chalk::IR::Node->new(
   298→            id => $node_id,
   299→            op => 'Equal',
   300→            inputs => [$current_control, $left_node->id, $right_node->id],
   301→            attributes => $attributes
   302→        );
   303→        $graph->add_node($cmp);
   304→        return $cmp;
   305→    }
   306→
   307→    # Control flow nodes
   308→    method build_if_node($condition_node) {
   309→        my $condition_ref = { op => 'NodeRef', node_id => $condition_node->id };
   310→        my $attributes = { condition => $condition_ref };
   311→        my $node_id = $self->next_node_id();
   312→        my $if_node = Chalk::IR::Node->new(
   313→            id => $node_id,
   314→            op => 'If',
   315→            inputs => [$current_control, $condition_node->id],
   316→            attributes => $attributes
   317→        );
   318→        $graph->add_node($if_node);
   319→        return $if_node;
   320→    }
   321→
   322→    method build_if_true_node($if_node) {
   323→        my $if_true = $self->build_proj_node($if_node, 0, 'IfTrue');
   324→        return $if_true;
   325→    }
   326→
   327→    method build_if_false_node($if_node) {
   328→        my $if_false = $self->build_proj_node($if_node, 1, 'IfFalse');
   329→        return $if_false;
   330→    }
   331→
   332→    method build_region_node(@control_inputs) {
   333→        my $empty_attrs = {};
   334→        my $node_id = $self->next_node_id();
   335→        my $region = Chalk::IR::Node->new(
   336→            id => $node_id,
   337→            op => 'Region',
   338→            inputs => \@control_inputs,
   339→            attributes => $empty_attrs
   340→        );
   341→        $graph->add_node($region);
   342→        return $region;
   343→    }
   344→
   345→    method build_phi_node($region_node, @value_inputs) {
   346→        my $empty_attrs = {};
   347→        my $node_id = $self->next_node_id();
   348→        my $phi = Chalk::IR::Node->new(
   349→            id => $node_id,
   350→            op => 'Phi',
   351→            inputs => [$region_node->id, @value_inputs],
   352→            attributes => $empty_attrs
   353→        );
   354→        $graph->add_node($phi);
   355→        return $phi;
   356→    }
   357→
   358→    # Loop control flow nodes
   359→    method build_loop_node($entry_control = undef) {
   360→        my $ctrl = $entry_control // $current_control // '__CONTROL_PLACEHOLDER__';
   361→        my $empty_attrs = {};
   362→        my $node_id = $self->next_node_id();
   363→        my $loop = Chalk::IR::Node->new(
   364→            id => $node_id,
   365→            op => 'Loop',
   366→            inputs => [$ctrl],  # Entry control; backedge added later
   367→            attributes => $empty_attrs
   368→        );
   369→        $graph->add_node($loop);
   370→        return $loop;
   371→    }
   372→
   373→    method build_loop_phi_node($loop_node, $initial_value, $loop_value = undef) {
   374→        # Loop phi starts with control and initial value
   375→        # Loop value added later (lazy phi pattern)
   376→        my @inputs = ($loop_node->id, $initial_value);
   377→        push @inputs, $loop_value if defined $loop_value;
   378→
   379→        my $empty_attrs = {};
   380→        my $node_id = $self->next_node_id();
   381→        my $phi = Chalk::IR::Node->new(
   382→            id => $node_id,
   383→            op => 'Phi',
   384→            inputs => \@inputs,
   385→            attributes => $empty_attrs
   386→        );
   387→        $graph->add_node($phi);
   388→        return $phi;
   389→    }
   390→
   391→    # Function call nodes
   392→    method build_call_node($function_name, @arg_nodes) {
   393→        # Call: control, memory, arguments...
   394→        # For now, use current_control for both control and memory
   395→        my $attributes = { function => $function_name };
   396→        my $node_id = $self->next_node_id();
   397→        my $call = Chalk::IR::Node->new(
   398→            id => $node_id,
   399→            op => 'Call',
   400→            inputs => [$current_control, $current_control, map { $_->id } @arg_nodes],
   401→            attributes => $attributes
   402→        );
   403→        $graph->add_node($call);
   404→        return $call;
   405→    }
   406→
   407→    # Loop-carried dependency tracking methods
   408→    method begin_loop_tracking() {
   409→        # Start tracking loop-carried dependencies
   410→        $loop_entry_scope = $scope->snapshot_bindings();
   411→        $loop_tracking_active = 1;
   412→        return;
   413→    }
   414→
   415→    method end_loop_tracking() {
   416→        # End tracking and clean up
   417→        $loop_entry_scope = undef;
   418→        $loop_tracking_active = 0;
   419→        return;
   420→    }
   421→
   422→    method is_tracking_loop() {
   423→        return $loop_tracking_active;
   424→    }
   425→
   426→    method loop_entry_scope() {
   427→        return $loop_entry_scope;
   428→    }
   429→
   430→    method generate_loop_phi_nodes($loop_node) {
   431→        # Generate phi nodes for all variables modified within the loop
   432→        return {} unless $loop_tracking_active;
   433→        return {} unless defined $loop_entry_scope;
   434→
   435→        # Capture current (loop-end) values before creating phis
   436→        my $loop_end_scope = $scope->snapshot_bindings();
   437→
   438→        # Find which variables were modified in the loop
   439→        my @modified_vars = $scope->find_modified_variables($loop_entry_scope);
   440→
   441→        # Generate a phi node for each modified variable
   442→        my %phis = ();
   443→        for my $var (@modified_vars) {
   444→            my $initial_value = $loop_entry_scope->{$var};
   445→            my $loop_value = $loop_end_scope->{$var};
   446→
   447→            # Create phi with initial value; backedge added later
   448→            my $phi = $self->build_loop_phi_node($loop_node, $initial_value, $loop_value);
   449→            $phis{$var} = $phi;
   450→
   451→            # Update scope to use phi node for this variable
   452→            # This ensures uses after the loop see the phi
   453→            $scope->define($var, $phi->id);
   454→        }
   455→
   456→        return \%phis;
   457→    }
   458→
   459→}
   460→
   461→1;
   462→

