     1→# ABOUTME: Validator for Sea of Nodes IR graphs checking SSA properties, CFG structure, dominance, and phi nodes
     2→# ABOUTME: Provides comprehensive validation infrastructure to catch IR construction errors before compilation
     3→use 5.42.0;
     4→use experimental qw(class builtin keyword_any keyword_all);
     5→use utf8;
     6→
     7→class Chalk::IR::Validator {
     8→    use Chalk::IR::Node;
     9→    use Chalk::IR::Graph;
    10→
    11→    # Main validation entry point - runs all validators
    12→    method validate_all($graph) {
    13→        my @all_errors = ();
    14→
    15→        # Run each validator and collect errors
    16→        push @all_errors, $self->validate_cfg($graph);
    17→        push @all_errors, $self->validate_single_assignment($graph);
    18→        push @all_errors, $self->validate_dominance($graph);
    19→        push @all_errors, $self->validate_phi_placement($graph);
    20→
    21→        my $success = scalar( @all_errors ) == 0 ? 1 : 0;
    22→        return ($success, \@all_errors);
    23→    }
    24→
    25→    # Validate Control Flow Graph structure
    26→    method validate_cfg($graph) {
    27→        my @errors = ();
    28→
    29→        # Check: Single Start node exists
    30→        my $start_count = 0;
    31→        my $start_id = undef;
    32→        my $nodes = $graph->nodes;
    33→
    34→        for my $node_id (keys( $nodes->%* )) {
    35→            my $node = $nodes->{$node_id};
    36→            if ($node->op eq 'Start') {
    37→                $start_count++;
    38→                $start_id = $node_id;
    39→            }
    40→        }
    41→
    42→        if ($start_count == 0) {
    43→            push @errors, "CFG validation failed: No Start node found in graph";
    44→        }
    45→        elsif ($start_count > 1) {
    46→            push @errors, "CFG validation failed: Multiple Start nodes found ($start_count), expected exactly 1";
    47→        }
    48→
    49→        # Check: At least one Return node exists
    50→        my $return_count = 0;
    51→        for my $node_id (keys( $nodes->%* )) {
    52→            my $node = $nodes->{$node_id};
    53→            if ($node->op eq 'Return') {
    54→                $return_count++;
    55→            }
    56→        }
    57→
    58→        if ($return_count == 0) {
    59→            push @errors, "CFG validation failed: No Return node found in graph";
    60→        }
    61→
    62→        # Check: All nodes reachable from Start (BFS traversal)
    63→        if (defined($start_id)) {
    64→            # Build successor map once for O(n+e) BFS instead of O(n²)
    65→            # In Sea of Nodes, inputs point TO this node FROM others,
    66→            # so we need to reverse the edges to get successors
    67→            my %successors = ();
    68→            for my $node_id (keys( $nodes->%* )) {
    69→                $successors{$node_id} = [];
    70→            }
    71→            for my $node_id (keys( $nodes->%* )) {
    72→                my $node = $nodes->{$node_id};
    73→                for my $input_id ($node->inputs->@*) {
    74→                    if (exists($nodes->{$input_id})) {
    75→                        push $successors{$input_id}->@*, $node_id;
    76→                    }
    77→                }
    78→            }
    79→
    80→            # BFS using successor map
    81→            my %reachable = ();
    82→            my @queue = ($start_id);
    83→            $reachable{$start_id} = 1;
    84→
    85→            while (scalar( @queue ) > 0) {
    86→                my $current_id = shift @queue;
    87→
    88→                # Follow all successors (nodes that depend on current node)
    89→                for my $successor_id ($successors{$current_id}->@*) {
    90→                    next if exists($reachable{$successor_id});
    91→                    $reachable{$successor_id} = 1;
    92→                    push @queue, $successor_id;
    93→                }
    94→            }
    95→
    96→            # Report unreachable nodes (except Constants which are data-only)
    97→            for my $node_id (keys( $nodes->%* )) {
    98→                if (not(exists($reachable{$node_id}))) {
    99→                    my $node = $nodes->{$node_id};
   100→                    # Constants are data-only nodes and don't need control flow reachability
   101→                    if ($node->op ne 'Constant') {
   102→                        push @errors, "CFG validation failed: Node $node_id is not reachable from Start node";
   103→                    }
   104→                }
   105→            }
   106→        }
   107→
   108→        return @errors;
   109→    }
   110→
   111→    # Validate SSA single assignment property
   112→    method validate_single_assignment($graph) {
   113→        my @errors = ();
   114→        my %assignments = ();  # variable_name => [node_ids]
   115→
   116→        my $nodes = $graph->nodes;
   117→
   118→        # Collect all Store nodes (variable assignments)
   119→        for my $node_id (keys( $nodes->%* )) {
   120→            my $node = $nodes->{$node_id};
   121→            if ($node->op eq 'Store') {
   122→                my $var_name = $node->attributes->{variable};
   123→                if (defined($var_name)) {
   124→                    $assignments{$var_name} //= [];
   125→                    push $assignments{$var_name}->@*, $node_id;
   126→                }
   127→            }
   128→        }
   129→
   130→        # Check for multiple assignments to same variable
   131→        for my $var_name (keys( %assignments )) {
   132→            my $assign_list = $assignments{$var_name};
   133→            if (scalar( $assign_list->@* ) > 1) {
   134→                my $node_list = join(', ', $assign_list->@*);
   135→                push @errors, "SSA violation: Variable $var_name is assigned more than once (in nodes: $node_list)";
   136→            }
   137→        }
   138→
   139→        return @errors;
   140→    }
   141→
   142→    # Compute dominance tree using Cooper/Harvey/Kennedy algorithm
   143→    method compute_dominance_tree($graph) {
   144→        my $nodes = $graph->nodes;
   145→        my %dom = ();  # node_id => immediate_dominator_id
   146→
   147→        # Find Start node
   148→        my $start_id = undef;
   149→        for my $node_id (keys( $nodes->%* )) {
   150→            my $node = $nodes->{$node_id};
   151→            if ($node->op eq 'Start') {
   152→                $start_id = $node_id;
   153→                last;
   154→            }
   155→        }
   156→
   157→        return \%dom unless defined($start_id);
   158→
   159→        # Compute node depths for _intersect heuristic
   160→        my $depth_map = $self->_compute_node_depths($graph);
   161→
   162→        # Build reverse graph (predecessors)
   163→        my %preds = ();  # node_id => [predecessor_ids]
   164→        for my $node_id (keys( $nodes->%* )) {
   165→            $preds{$node_id} = [];
   166→        }
   167→
   168→        for my $node_id (keys( $nodes->%* )) {
   169→            my $node = $nodes->{$node_id};
   170→            for my $input_id ($node->inputs->@*) {
   171→                if (exists($nodes->{$input_id})) {
   172→                    push $preds{$node_id}->@*, $input_id;
   173→                }
   174→            }
   175→        }
   176→
   177→        # Initialize: Start dominates itself
   178→        $dom{$start_id} = $start_id;
   179→
   180→        # Iterative dataflow until convergence
   181→        my $changed = 1;
   182→        my $max_iterations = scalar( keys( $nodes->%* ) ) * 2;
   183→        my $iterations = 0;
   184→
   185→        while ($changed) {
   186→            if ($iterations > $max_iterations) {
   187→                last;
   188→            }
   189→            $changed = 0;
   190→            $iterations++;
   191→
   192→            for my $node_id (keys( $nodes->%* )) {
   193→                next if $node_id eq $start_id;
   194→
   195→                my @pred_list = $preds{$node_id}->@*;
   196→                next if scalar( @pred_list ) == 0;
   197→
   198→                # Find first processed predecessor
   199→                my $new_idom = undef;
   200→                for my $pred_id (@pred_list) {
   201→                    if (exists($dom{$pred_id})) {
   202→                        $new_idom = $pred_id;
   203→                        last;
   204→                    }
   205→                }
   206→
   207→                next unless defined($new_idom);
   208→
   209→                # Intersect with all other predecessors
   210→                for my $pred_id (@pred_list) {
   211→                    next if $pred_id eq $new_idom;
   212→                    next unless exists($dom{$pred_id});
   213→
   214→                    $new_idom = $self->_intersect(\%dom, $pred_id, $new_idom, $depth_map);
   215→                }
   216→
   217→                # Update if changed
   218→                if (not(exists($dom{$node_id}))) {
   219→                    $dom{$node_id} = $new_idom;
   220→                    $changed = 1;
   221→                }
   222→                elsif ($dom{$node_id} ne $new_idom) {
   223→                    $dom{$node_id} = $new_idom;
   224→                    $changed = 1;
   225→                }
   226→            }
   227→        }
   228→
   229→        return \%dom;
   230→    }
   231→
   232→    # Helper: Find intersection of two nodes in dominance tree
   233→    method _intersect($dom, $b1, $b2, $depth_map = undef) {
   234→        my $finger1 = $b1;
   235→        my $finger2 = $b2;
   236→
   237→        while ($finger1 ne $finger2) {
   238→            # Move up dominance tree
   239→            while ($self->_node_depth($finger1, $depth_map) > $self->_node_depth($finger2, $depth_map)) {
   240→                $finger1 = $dom->{$finger1};
   241→                last unless defined($finger1);
   242→            }
   243→            last unless defined($finger1);
   244→
   245→            while ($self->_node_depth($finger2, $depth_map) > $self->_node_depth($finger1, $depth_map)) {
   246→                $finger2 = $dom->{$finger2};
   247→                last unless defined($finger2);
   248→            }
   249→            last unless defined($finger2);
   250→
   251→            if ($finger1 eq $finger2) {
   252→                last;
   253→            }
   254→
   255→            # Both at same depth, move up together
   256→            $finger1 = $dom->{$finger1};
   257→            $finger2 = $dom->{$finger2};
   258→
   259→            last unless defined($finger1);
   260→            last unless defined($finger2);
   261→        }
   262→
   263→        return $finger1;
   264→    }
   265→
   266→    # Helper: Compute CFG depth for all nodes via BFS from Start
   267→    # Returns hashref mapping node_id => depth
   268→    method _compute_node_depths($graph) {
   269→        my $nodes = $graph->nodes;
   270→        my %depths = ();
   271→
   272→        # Find Start node
   273→        my $start_id = undef;
   274→        for my $node_id (keys( $nodes->%* )) {
   275→            my $node = $nodes->{$node_id};
   276→            if ($node->op eq 'Start') {
   277→                $start_id = $node_id;
   278→                last;
   279→            }
   280→        }
   281→
   282→        return \%depths unless defined($start_id);
   283→
   284→        # BFS to compute depths
   285→        my @queue = ($start_id);
   286→        $depths{$start_id} = 0;
   287→
   288→        while (scalar( @queue ) > 0) {
   289→            my $current_id = shift @queue;
   290→            my $current_depth = $depths{$current_id};
   291→
   292→            # Find all nodes that have current_id as input
   293→            for my $node_id (keys( $nodes->%* )) {
   294→                next if exists($depths{$node_id});
   295→                my $node = $nodes->{$node_id};
   296→
   297→                for my $input_id ($node->inputs->@*) {
   298→                    if ($input_id eq $current_id) {
   299→                        $depths{$node_id} = $current_depth + 1;
   300→                        push @queue, $node_id;
   301→                        last;
   302→                    }
   303→                }
   304→            }
   305→        }
   306→
   307→        return \%depths;
   308→    }
   309→
   310→    # Helper: Get node depth from cached depth map
   311→    # Falls back to parsing node_id for backward compatibility
   312→    method _node_depth($node_id, $depth_map = undef) {
   313→        return 0 unless defined($node_id);
   314→
   315→        # Use cached depth if available
   316→        if (defined($depth_map) && exists($depth_map->{$node_id})) {
   317→            return $depth_map->{$node_id};
   318→        }
   319→
   320→        # Fallback: parse node_id (e.g., "node_123" => 123)
   321→        # This is a heuristic and may not reflect true CFG depth
   322→        my $pattern = qr/node_(\d+)/;
   323→        if ($node_id =~ $pattern) {
   324→            return $1;
   325→        }
   326→        return 0;
   327→    }
