   329→    # Validate dominance property: definitions dominate uses
   330→    method validate_dominance($graph) {
   331→        my @errors = ();
   332→
   333→        my $dom_tree = $self->compute_dominance_tree($graph);
   334→        my $nodes = $graph->nodes;
   335→
   336→        # Check each Load node: its Store must exist and be valid
   337→        for my $node_id (keys( $nodes->%* )) {
   338→            my $node = $nodes->{$node_id};
   339→            if ($node->op eq 'Load') {
   340→                my $var_name = $node->attributes->{variable};
   341→                my $store_id = $node->attributes->{store_id};
   342→
   343→                if (defined($store_id)) {
   344→                    if (defined($var_name)) {
   345→                        # Check if store exists
   346→                        if (not(exists($nodes->{$store_id}))) {
   347→                            push @errors, "Dominance violation: Load of $var_name in $node_id references non-existent Store $store_id";
   348→                            next;
   349→                        }
   350→
   351→                        my $store_node = $nodes->{$store_id};
   352→                        if ($store_node->op ne 'Store') {
   353→                            push @errors, "Dominance violation: Load of $var_name in $node_id references $store_id which is not a Store node";
   354→                            next;
   355→                        }
   356→
   357→                        # For graphs with control flow (Region nodes), check strict dominance
   358→                        # For linear graphs (Chapters 1-4), the store_id reference is sufficient
   359→                        my $has_control_flow = $self->_has_control_flow($graph);
   360→
   361→                        if ($has_control_flow) {
   362→                            my $is_dominated = $self->_dominates($dom_tree, $store_id, $node_id);
   363→                            if (not($is_dominated)) {
   364→                                push @errors, "Dominance violation: Load of $var_name in $node_id is not dominated by its Store in $store_id";
   365→                            }
   366→                        }
   367→                    }
   368→                }
   369→            }
   370→        }
   371→
   372→        return @errors;
   373→    }
   374→
   375→    # Helper: Check if graph has control flow (Region/If nodes)
   376→    method _has_control_flow($graph) {
   377→        my $nodes = $graph->nodes;
   378→        for my $node_id (keys( $nodes->%* )) {
   379→            my $node = $nodes->{$node_id};
   380→            if ($node->op eq 'Region' || $node->op eq 'If') {
   381→                return 1;
   382→            }
   383→        }
   384→        return 0;
   385→    }
   386→
   387→    # Helper: Check if dominator_id dominates target_id
   388→    method _dominates($dom_tree, $dominator_id, $target_id) {
   389→        return 1 if $dominator_id eq $target_id;
   390→
   391→        # Walk up dominance tree from target
   392→        my $current = $target_id;
   393→        my $max_steps = 100;
   394→        my $steps = 0;
   395→
   396→        while (defined($current)) {
   397→            if ($steps > $max_steps) {
   398→                last;
   399→            }
   400→            $steps++;
   401→
   402→            if (exists($dom_tree->{$current})) {
   403→                $current = $dom_tree->{$current};
   404→                if (defined($current)) {
   405→                    if ($current eq $dominator_id) {
   406→                        return 1;
   407→                    }
   408→                }
   409→            }
   410→            else {
   411→                last;
   412→            }
   413→        }
   414→
   415→        return 0;
   416→    }
   417→
   418→    # Validate phi node placement (prepare for Chapter 5)
   419→    method validate_phi_placement($graph) {
   420→        my @errors = ();
   421→
   422→        my $nodes = $graph->nodes;
   423→
   424→        # Check each Phi node
   425→        for my $node_id (keys( $nodes->%* )) {
   426→            my $node = $nodes->{$node_id};
   427→            next unless $node->op eq 'Phi';
   428→
   429→            # Phi must be at a Region (control flow merge point)
   430→            my $phi_inputs = $node->inputs;
   431→            if (scalar( $phi_inputs->@* ) == 0) {
   432→                push @errors, "Phi node $node_id has no control input (must connect to Region)";
   433→                next;
   434→            }
   435→
   436→            my $region_id = $phi_inputs->[0];
   437→            if (exists($nodes->{$region_id})) {
   438→                my $region_node = $nodes->{$region_id};
   439→                if ($region_node->op ne 'Region' && $region_node->op ne 'Loop') {
   440→                    push @errors, "Phi node $node_id is not at a Region/Loop merge point (control input is " . $region_node->op . ")";
   441→                }
   442→                else {
   443→                    # Count region/loop predecessors
   444→                    my $region_preds = $region_node->inputs;
   445→                    my $expected_alternatives = scalar( $region_preds->@* );
   446→
   447→                    # Count phi alternatives from standardized inputs array
   448→                    # Phi nodes use inputs array: inputs => [ctrl, val1, val2, ...]
   449→                    # This is the standardized representation as per GitHub Issue #80
   450→                    my $phi_inputs = $node->inputs;
   451→                    my $actual_alternatives = scalar( $phi_inputs->@* ) - 1;  # Subtract control input
   452→
   453→                    if ($actual_alternatives != $expected_alternatives) {
   454→                        push @errors, "Phi node $node_id in node $region_id expects $expected_alternatives value inputs ($expected_alternatives predecessors) but has $actual_alternatives";
   455→                    }
   456→                }
   457→            }
   458→            else {
   459→                push @errors, "Phi node $node_id references non-existent Region $region_id";
   460→            }
   461→        }
   462→
   463→        return @errors;
   464→    }
   465→}
